import {VERSION,PHASES,PAUSED,newProfile,recordFor,stageFor,statusFor,candidates,teach,applyResult,finishStep,metrics,csvCell,validateBackup} from './engine.js';
import {openStore,writeState} from './storage.js';
import {renderTreasureMap,renderClueVisual} from './treasure-visuals.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chestEmblem="<svg class=\"treasure-chest-icon\" viewBox=\"0 0 64 64\" aria-hidden=\"true\"><path d=\"M9 28q0-20 23-20t23 20v7H9Z\" fill=\"#dc8a34\" stroke=\"#69412a\" stroke-width=\"4\"/><rect x=\"8\" y=\"30\" width=\"48\" height=\"27\" rx=\"5\" fill=\"#92532e\" stroke=\"#543421\" stroke-width=\"4\"/><path d=\"M26 30h12v27H26Z\" fill=\"#f5c548\"/><rect x=\"29\" y=\"34\" width=\"7\" height=\"9\" rx=\"2\" fill=\"#744e24\"/></svg>";
const avatars={hiker:'🧭',fox:'🗝️',bird:'⚓',bear:'🗺️',compass:'🧭',chest:chestEmblem,ship:'⛵',anchor:'⚓',key:'🗝️',spyglass:'🔭',gem:'💎',map:'🗺️'};
const avatarLabels={hiker:'Compass',fox:'Golden key',bird:'Anchor',bear:'Treasure map',compass:'Compass',chest:'Treasure chest',ship:'Pirate ship',anchor:'Anchor',key:'Golden key',spyglass:'Spyglass',gem:'Gemstone',map:'Treasure map'};
const paths={trail:'M12 2 16 10 22 12 16 14 12 22 8 14 2 12 8 10Z M12 8v8m-4-4h8',book:'M3 5c4-2 6-2 9 0 3-2 5-2 9 0v15c-4-2-6-2-9 0-3-2-5-2-9 0Zm9 0v15',chart:'M4 20h17M6 16v-4m6 4V6m6 10V3',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',leaf:'M20 3C5 1 1 17 9 20c7 3 12-9 11-17ZM6 19 16 8',flask:'M8 3h8m-6 0v7l-6 9c-1 2 1 2 2 2h12c1 0 3 0 2-2l-6-9V3M7 16h10',audio:'M4 9h4l5-5v16l-5-5H4Zm13-2c4 3 4 7 0 10m0-6c1 1 1 1 0 2',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L20 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2'};
const icon=(id)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.spark}"/></svg>`;
let pack,state,task=null,saveQueue=Promise.resolve(),toastTimer,registration,offlineReady=false,offlineError='',installPrompt,sessionSteps=0,reviewOnly=false;
let activeTimer={total:0,start:0};
let currentAudio,recoveryData;
const profile=()=>state.profiles.find(p=>p.id===state.activeId)||state.profiles[0];
const unit=()=>pack.units.find(u=>u.id===profile().unit);
const paused=()=>PAUSED.has(state.settings.phase);
const phaseNames={learning:'Ongoing learning',orientation:'Orientation',baseline:'Baseline assessment',intervention:'Intervention',immediate:'Immediate assessment',retention:'Retention interval',delayed:'Delayed assessment',released:'Study complete'};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function save(){
  $('#save-status').textContent='Saving progress…';
  const snapshot=structuredClone(state);
  saveQueue=saveQueue.catch(()=>{}).then(()=>writeState(snapshot));
  try{await saveQueue;$('#save-status').textContent='Saved on this device';}
  catch{ $('#save-status').textContent='Not saved — export a backup';toast('Your progress could not be saved. Export a backup in Teacher settings.'); }
}
function startTimer(){activeTimer={total:0,start:document.hidden?0:performance.now()};}
function elapsed(){return activeTimer.total+(activeTimer.start?performance.now()-activeTimer.start:0);}
function stopTimer(){activeTimer.total=elapsed();activeTimer.start=0;}
document.addEventListener('visibilitychange',()=>{if(!task||task.stage==='teach'||task.stage==='study')return;if(document.hidden)stopTimer();else if(!task.event)activeTimer.start=performance.now();});
function connection(){const online=navigator.onLine;$('#connection').innerHTML=`<i></i>${online?'Connected':'Offline'}`;$('#connection').classList.toggle('offline',!online);}
window.addEventListener('online',connection);window.addEventListener('offline',connection);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
function nav(){const view=(location.hash.slice(1)||'trail');$('#navigation').innerHTML=[['trail','trail','Treasure map'],['words','book','My chest'],['progress','chart','Voyage progress']].map(([id,ic,label])=>`<button class="nav-button ${id===view?'active':''}" data-view="${id}" aria-label="${label}" ${id===view?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('');$('#navigation').querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.view;});$('#page-label').textContent={trail:'Treasure map',words:'My chest',progress:'Voyage progress'}[view]||'Treasure map';const p=profile();$('#profile-switch').innerHTML=`<span class="avatar">${avatars[p.avatar]||'🧭'}</span><span class="profile-name">${esc(p.name)}</span><span class="chevron">⌄</span>`;document.body.classList.toggle('reduced-motion',state.settings.reducedMotion);}
function heading(title,subtitle){return `<div class="page-heading"><div><div class="eyebrow">YOUR TREASURE VOYAGE</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="stars-pill"><span class="star" aria-hidden="true">🪙</span><div><b>${profile().stars}</b><small>GOLD COINS</small></div></div></div>`;}

function missionBrief(){
  const p=profile(),m=metrics(p,pack.words),u=unit(),words=pack.words.filter(w=>w.unit===u.id);
  const explored=words.filter(w=>p.records[w.id]?.taught).length;
  const mission=m.due>0
    ?{cls:'review',icon:'↻',type:'TREASURE REVIEW',title:'Reopen a clue',detail:`${m.due} word${m.due===1?' is':'s are'} ready for another attempt.`}
    :explored<words.length
      ?{cls:'discovery',icon:'✦',type:'CLUE MISSION',title:'Find a new treasure',detail:'Meet a word, then remember it.'}
      :{cls:'mastery',icon:'◆',type:'CAPTAIN’S CHALLENGE',title:'Guard your treasures',detail:'Revisit words to keep them fresh.'};
  return `<section class="mission-brief ${mission.cls}" aria-label="Current vocabulary mission"><span class="mission-icon" aria-hidden="true">${mission.icon}</span><div class="mission-copy"><small>${mission.type} · UNIT ${u.id}</small><h2>${mission.title}</h2><p>${mission.detail}</p></div><span class="mission-status">AT YOUR PACE</span></section>`;
}
function pauseBanner(){return paused()?`<div class="paused-banner">${esc(phaseNames[state.settings.phase])}: target-word practice is paused for this learner group.</div>`:'';}
function offlineBanner(){return `<div class="offline-banner">${icon('download')}<div><strong>${offlineReady?'Ready for your offline treasure hunt':'Take your learning anywhere'}</strong><p>${offlineReady?'Your app, word cards and pronunciation are saved for offline learning.':'Save the complete pack once, then learn without an internet connection.'}</p></div><button class="secondary" data-offline>${offlineReady?'Offline details':'Save for offline'}</button></div>`;}
function renderTrail(){
 const p=profile(),u=unit(),m=metrics(p,pack.words),uw=pack.words.filter(w=>w.unit===u.id),seen=uw.filter(w=>p.records[w.id]?.taught).length;
 const destination=p.position<10?'Sandy Island':p.position<20?'Whispering Cave':'Treasure Cove';
 return heading('Your next clue awaits.','Find words, unlock treasures and remember what you discover.')+pauseBanner()+missionBrief()+
 `<div class="trail-layout">
   <section class="trail-card treasure-map-card">${renderTreasureMap(p.position,p.lap)}
     <div class="map-top"><div><span class="map-tag">${icon('trail')} TREASURE MAP</span><div class="map-heading">${destination}</div></div><span class="altitude">VOYAGE ${p.lap}</span></div>
   </section>
   <section class="next-card"><div class="card-label">NEXT DESTINATION <span class="badge-tiny">UNIT ${u.id}</span></div>
     <h2>${esc(u.title)}</h2><p>${esc(u.domain)}.</p>
     <div class="trail-stats"><div><strong>${seen}<span style="font-size:13px"> / ${uw.length}</span></strong><span>WORDS DISCOVERED</span></div><div><strong>${m.due}</strong><span>READY TO REVIEW</span></div></div>
     <div class="session-dots" aria-label="${sessionSteps%6} of 6 clues in this session">${Array.from({length:6},(_,i)=>`<span class="${i<sessionSteps%6?'done':''}"></span>`).join('')}</div>
     <div class="session-info">6 clues per session · No timer</div>
     <button class="primary next-move" id="start-learning" ${paused()?'disabled':''}>${paused()?'Practice paused':m.due?'Start review':sessionSteps?'Continue hunt':'Start hunt'} <span class="cta-arrow" aria-hidden="true">→</span></button>
   </section>
 </div>`+offlineBanner()+
 `<div class="section-heading"><h2>Choose an island</h2><small>${pack.units.length} units · ${pack.words.length} vocabulary cards</small></div>
 <div class="units-grid">${pack.units.map(u=>{const words=pack.words.filter(w=>w.unit===u.id),n=words.filter(w=>p.records[w.id]?.taught).length;return `<button class="unit-card ${u.id===p.unit?'active':''}" data-unit="${u.id}" ${paused()?'disabled':''} aria-pressed="${u.id===p.unit}">
 <span class="unit-symbol">🏝️</span><span class="unit-number">ISLAND ${u.id}</span><span class="unit-title">${esc(u.title)}</span><small>${esc(u.subtitle)}</small><div class="unit-progress"><span style="width:${words.length?Math.round(n/words.length*100):0}%"></span></div><small>${n} / ${words.length} discovered</small></button>`}).join('')}</div>`;
}
function renderWords(){return heading('My word chest.','Open a word you have discovered to see, hear and revisit it.')+pauseBanner()+(paused()?`<div class="paused-card"><h2>Your word chest is resting for this study phase.</h2><p>The research targets are paused during ${esc(phaseNames[state.settings.phase].toLowerCase())}. Your progress is safe. Your teacher will reopen practice at the appropriate point.</p></div>`:`<div class="search-bar"><input id="word-search" type="search" placeholder="Find a word…" aria-label="Search your chest"><select id="word-filter" aria-label="Filter vocabulary unit"><option value="all">All units</option>${pack.units.map(u=>`<option value="${u.id}">Unit ${u.id}</option>`).join('')}</select></div><div id="words-list" class="words-grid"></div>`);}
function wordsList(){const search=$('#word-search')?.value.trim().toLowerCase()||'',filter=$('#word-filter')?.value||'all';const words=pack.words.filter(w=>profile().records[w.id]?.taught&&(filter==='all'||String(w.unit)===filter)&&(w.word.toLowerCase().includes(search)||w.meaning.toLowerCase().includes(search)));$('#words-list').innerHTML=words.map(w=>`<button class="word-card" data-word="${w.id}"><span aria-hidden="true">${w.emoji}</span><div><h3>${esc(w.word)}</h3><p>Unit ${w.unit} · ${esc(w.pos)}</p><small>${statusFor(profile().records[w.id])}</small></div></button>`).join('')||'<div class="empty">No treasures here yet. Discover a word on the map.</div>';$('#words-list').querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>openTask(pack.words.find(w=>w.id===b.dataset.word),true));}
function fmtDate(n){return n?new Date(n).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'—';}
function renderProgress(){const p=profile(),m=metrics(p,pack.words);const rows=pack.words.filter(w=>p.records[w.id]?.taught);return heading('Voyage progress.','Your practice history and treasures found.')+pauseBanner()+`<div class="metrics-grid"><div class="metric"><strong>${m.seen}<span> / ${pack.words.length}</span></strong><span>Words explored</span></div><div class="metric"><strong>${m.secure}</strong><span>Secure for now</span></div><div class="metric"><strong>${m.due}</strong><span>Ready to revisit</span></div><div class="metric"><strong>${Math.floor(m.activeMs/60000)}m ${Math.round(m.activeMs/1000)%60}s</strong><span>Active answer time</span></div></div><section class="report-card"><h2>Your independent practice</h2><p>Answers completed without hints. These practice results are separate from the thesis vocabulary tests.</p>${[['recognition','Meaning recognition'],['recall','Word recall'],['context','Context challenge']].map(([k,label])=>{const v=m[k];return `<div class="accuracy-row"><span>${label}</span><div class="bar"><i style="width:${v.accuracy??0}%"></i></div><small>${v.total?`${v.accuracy}% · ${v.correct}/${v.total} answers`:'Not yet assessed'}</small></div>`}).join('')}<p>${m.assisted} supported attempts · ${m.total} total attempts. Hints help you learn; supported answers are recorded separately.</p><button class="primary next-move" id="review-due" ${paused()||!m.due?'disabled':''}>Revisit due words <span aria-hidden="true">→</span></button></section><section class="report-card"><h2>Treasure milestones</h2><div class="badge-row">${p.badges.length?p.badges.map(b=>`<div class="earned-badge"><span aria-hidden="true">${b==='summit'?'🗝️':'🪙'}</span><div>${b==='summit'?'Treasure explorer':'First six clues'}<small>${b==='summit'?'A completed treasure voyage':'A short session completed'}</small></div></div>`).join(''):'<p>Your first milestone is waiting. Complete six clues to earn it.</p>'}</div><p style="margin-top:14px;margin-bottom:0">Milestones celebrate participation. Vocabulary knowledge grows through independent practice across sessions.</p></section><section class="report-card"><h2>Your words at a glance</h2>${rows.length?`<div class="table-wrap"><table class="report-table"><thead><tr><th>Word</th><th>Learning status</th><th>Independent recall</th><th>Next review</th></tr></thead><tbody>${rows.map(w=>{const r=p.records[w.id];return `<tr><td>${esc(w.word)}</td><td>${statusFor(r)}</td><td>${r.independent.recall}</td><td>${r.dueAt<=Date.now()?'Ready now':fmtDate(r.dueAt)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><strong>Your journey starts with one word.</strong>Explore a vocabulary card to begin your learning record.</div>'}</section>`;}
function render(){if(!state||!pack)return;nav();const view=location.hash.slice(1)||'trail';$('#main').innerHTML=view==='words'?renderWords():view==='progress'?renderProgress():renderTrail();connection();$('#start-learning')?.addEventListener('click',()=>startLearning(metrics(profile(),pack.words).due>0));$('#review-due')?.addEventListener('click',()=>startLearning(true));document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=async()=>{profile().unit=Number(b.dataset.unit);reviewOnly=false;sessionSteps=0;render();await save();});document.querySelectorAll('[data-offline]').forEach(b=>b.onclick=showOffline);$('#source-details')?.addEventListener('click',e=>{e.preventDefault();showTeacher();});if(view==='words'&&!paused()){wordsList();$('#word-search').oninput=wordsList;$('#word-filter').onchange=wordsList;}}
window.addEventListener('hashchange',()=>{render();});
function startLearning(review=false){if(paused()){toast('Target-word practice is paused in this study phase.');return;}reviewOnly=review;const choices=candidates(profile(),pack.words,profile().unit,review);if(!choices.length){toast('No words are due. Choose an island to find a new clue.');return;}openTask(choices[0]);}
function makeOptions(word){const others=pack.words.filter(w=>w.id!==word.id);const compatible=others.filter(w=>w.pos===word.pos&&w.unit===word.unit);const pool=[...compatible,...others.filter(w=>!compatible.includes(w))];const start=profile().turn%Math.max(1,compatible.length);const picks=[];for(let i=0;i<pool.length&&picks.length<3;i++){const w=pool[(start+i)%pool.length];if(!picks.includes(w.word))picks.push(w.word);}const all=[word.word,...picks];for(let i=all.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[all[i],all[j]]=[all[j],all[i]];}return all;}
function openTask(word,studyOnly=false){if(paused())return;const p=profile(),r=recordFor(p,word.id);task={word,wordId:word.id,stage:studyOnly?'study':stageFor(r),variant:r.attempts%2,packVersion:pack.version,options:makeOptions(word),hint:0,assistance:[],event:null,retry:false,interaction:['choice','match','drag'][(p.turn+pack.words.findIndex(x=>x.id===word.id))%3],selected:null};if(state.settings.translation&&task.stage!=='teach'&&task.stage!=='study'){task.assistance.push('translation');task.hint=1;}drawTask();if(!$('#task-dialog').open)$('#task-dialog').showModal();startTimer();}
function drawTask(){if(!task)return;const t=task,w=t.word,study=['teach','study'].includes(t.stage),reveal=study||!!t.event||t.hint>=3;const title=study?w.word:{recognition:'Find the word',recall:'Bring the word to mind',context:'Use the word in context'}[t.stage];const stageLabel=study?'MEET A WORD':{recognition:'MEANING RECOGNITION',recall:'WORD RECALL',context:'CONTEXT CHALLENGE'}[t.stage];const sentence=w.sentences[t.variant];
  let content='';
  if(study){content=`<div class="word-meta">${esc(w.pos)} · UNIT ${w.unit}</div><h2 id="task-title">${esc(title)}</h2><p class="definition">${esc(w.meaning)}</p><details class="translation-note"><summary>Malay meaning (optional)</summary><p>${esc(w.translation)}</p></details><button class="audio-button" id="play-audio">${icon('audio')} Hear pronunciation</button><div class="context-sentence">${esc(w.example)}</div><p class="feedback-note">See the clue, listen, then try recalling the word.</p>`;}
  else {content=`<div class="word-meta">UNIT ${w.unit} · ${esc(stageLabel)}</div><h2 id="task-title">${title}</h2>${t.stage!=='context'?`<p class="definition">${esc(w.meaning)}</p>`:'<p class="definition">Complete the sentence with the word you’ve been learning.</p>'}${t.stage!=='recall'?`<div class="context-sentence">${esc(sentence)}</div>`:''}`;
    if(t.hint){const hint=t.stage==='recognition'&&t.hint===1?`Two choices are set aside. Meaning in Malay: ${esc(w.translation)}.`:t.hint===1?`Meaning in Malay: ${esc(w.translation)}`:t.hint===2?`First letter: <strong>${esc(w.word.charAt(0).toUpperCase())}</strong>. ${w.word.includes(' ')?'This answer has '+w.word.split(' ').length+' words.':'Think about the meaning, then try its spelling.'}`:`The word is <strong>${esc(w.word)}</strong>. ${esc(w.meaning)}`;content+=`<div class="hint-area">${hint}</div>`;}
    if(t.stage==='recognition'){
      const keep=t.options.find(o=>o!==w.word);
      const choices=t.options.map(o=>({word:o,eliminated:t.hint>=1&&o!==w.word&&o!==keep}));
      if(t.interaction==='choice'){
        content+=`<p class="interaction-prompt">Choose the word that matches the clue.</p><div class="options">${choices.map(({word:o,eliminated})=>`<button class="option ${eliminated?'eliminated':''} ${t.event&&o===w.word?'right':''} ${t.event&&o===t.event.answer&&!t.event.correct?'wrong':''}" data-answer="${esc(o)}" ${t.event||eliminated?'disabled':''}>${esc(o)}</button>`).join('')}</div>`;
      } else {
        const isDrag=t.interaction==='drag';
        content+=`<div class="interaction-label">${isDrag?'DRAG OR TAP':'TAP TO MATCH'}</div><p class="interaction-prompt">${isDrag?'Drag a word into the answer zone, or tap a word then tap the zone.':'Select a word, then tap the matching clue below.'}</p><div class="word-tiles">${choices.map(({word:o,eliminated})=>`<button type="button" class="word-tile ${t.selected===o?'selected':''} ${eliminated?'eliminated':''} ${t.event&&o===w.word?'right':''} ${t.event&&o===t.event.answer&&!t.event.correct?'wrong':''}" data-pick="${esc(o)}" draggable="${!t.event&&!eliminated&&isDrag}" aria-pressed="${t.selected===o}" ${t.event||eliminated?'disabled':''}>${esc(o)}</button>`).join('')}</div><button type="button" class="matching-zone ${t.selected?'filled':''}" id="matching-zone" ${t.event?'disabled':''} aria-label="${isDrag?'Drop or tap to submit selected word':'Tap to match selected word'}"><span class="match-symbol" aria-hidden="true">${isDrag?'↓':'↔'}</span><span>${t.selected?esc(t.selected):isDrag?'Drop a word here':'Select a word above'}<small>${isDrag?'ANSWER ZONE':'MATCH TO THIS CLUE'}</small></span></button>`;
      }
    }
    else {content+=`<form id="answer-form" class="answer-form"><label for="typed-answer">Type the English word${w.word.includes(' ')?' or phrase':''}</label><input id="typed-answer" autocomplete="off" autocapitalize="none" spellcheck="false" required maxlength="100" ${t.event?'disabled':''} ${t.event?`value="${esc(t.event.answer)}"`:''}><button class="primary" type="submit" ${t.event?'disabled':''}>Check my answer</button></form>`;}
    if(t.event){const e=t.event;content+=`<div class="feedback ${e.correct?'':'error'}" role="status">${e.correct?`<span class="chest-reward" aria-hidden="true">${chestEmblem}</span>`:''}<strong>${e.correct?(e.assistance.length?'Good use of a hint — keep practising.':({recognition:'Treasure unlocked!',recall:'Clue remembered!',context:'Treasure unlocked!'})[t.stage]):'Not quite — check the connection.'}</strong><p>${e.correct?`<b>${esc(w.word)}</b> — ${esc(w.meaning)}<br>+${e.stars} coins. ${e.assistance.length?'We’ll revisit this word without support later.':'A useful step in your learning.'}`:`The word is <b>${esc(w.word)}</b>. ${esc(w.meaning)}<br>${esc(w.example)}${e.answer&&pack.words.find(x=>x.word===e.answer)?`<br><b>${esc(e.answer)}</b>: ${esc(pack.words.find(x=>x.word===e.answer).meaning)}`:''}`}</p></div><button class="audio-button" id="play-audio">${icon('audio')} Hear ${esc(w.word)}</button>`;}
    else {content+=`<div class="support-row"><button class="text-button" id="more-support">${icon('spark').replace('<svg','<svg width="14" height="14"')} ${t.hint>=3?'Hear the word':'Need a clue?'}</button><small>Always free</small></div>`;}
  }
  const footer=study?`<span>${t.stage==='study'?'Your word chest':'Learning before retrieval'}</span><button class="primary next-move" id="after-study">${t.stage==='study'?'Back to my words':'Try the clue'} <span class="cta-arrow" aria-hidden="true">→</span></button>`:t.event?`<span>${t.event.correct?(t.event.assistance.length?'Supported practice recorded':'Independent practice recorded'):'An error is a place to learn.'}</span><div class="button-row">${!t.event.correct&&!t.retry?'<button class="secondary" id="retry-word">Try with support</button>':''}<button class="primary next-move" id="next-word">${t.event.correct?'Continue voyage':'Review this clue'} <span class="cta-arrow" aria-hidden="true">→</span></button></div>`:`<span>${t.assistance.length?'Supported practice':'Try it independently. Ask for help anytime.'}</span><span>No timer · Accuracy matters</span>`;
  $('#task-dialog').innerHTML=`<div class="dialog-top"><div class="eyebrow">${stageLabel}</div><button class="close-button" id="close-task" aria-label="Close vocabulary card">×</button></div><div class="task-content focused"><div class="task-body">${reveal?renderClueVisual(w):''}${content}</div></div><div class="task-footer">${footer}</div>`;
  $('#close-task').onclick=closeTask;
  $('#play-audio')?.addEventListener('click',()=>playAudio(w));
  $('#after-study')?.addEventListener('click',async()=>{if(t.stage==='study'){teach(profile(),w.id);await save();closeTask();return;}teach(profile(),w.id);await save();t.stage='recognition';if(state.settings.translation){t.assistance=['translation'];t.hint=1;}drawTask();startTimer();});
  $('#task-dialog').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>submitAnswer(b.dataset.answer));
  $('#task-dialog').querySelectorAll('[data-pick]').forEach(btn=>{
    btn.addEventListener('click',()=>{if(t.event)return;t.selected=btn.dataset.pick;drawTask();});
    btn.addEventListener('dragstart',event=>{if(t.event){event.preventDefault();return;}event.dataTransfer.setData('text/plain',btn.dataset.pick);event.dataTransfer.effectAllowed='move';});
  });
  const matchZone=$('#matching-zone');
  if(matchZone){
    matchZone.addEventListener('click',()=>{if(t.selected&&!t.event)submitAnswer(t.selected);});
    matchZone.addEventListener('dragover',event=>{if(t.interaction==='drag'&&!t.event){event.preventDefault();matchZone.classList.add('drag-over');}});
    matchZone.addEventListener('dragleave',()=>matchZone.classList.remove('drag-over'));
    matchZone.addEventListener('drop',event=>{event.preventDefault();matchZone.classList.remove('drag-over');if(t.interaction!=='drag'||t.event)return;const answer=event.dataTransfer.getData('text/plain');if(t.options.includes(answer))submitAnswer(answer);});
  }
  $('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();submitAnswer($('#typed-answer').value);});
  $('#more-support')?.addEventListener('click',()=>{if(t.hint>=3){playAudio(w);return;}const input=$('#typed-answer')?.value||'';t.hint++;t.assistance.push('hint-'+t.hint);drawTask();if($('#typed-answer'))$('#typed-answer').value=input;});
  $('#retry-word')?.addEventListener('click',()=>{t.event=null;t.retry=true;t.hint=Math.max(2,t.hint);t.assistance.push('worked-answer-retry');drawTask();startTimer();});
  $('#next-word')?.addEventListener('click',async()=>{const e=t.event;const summit=finishStep(profile(),e.correct,e.assistance.length>0);sessionSteps++;await save();closeTask();if(summit)toast('Treasure checkpoint reached! Return to review words later.');else if(sessionSteps%6===0)toast('Six clues completed. Take a break, or keep exploring.');else toast(e.correct?'Treasure found. This word stays in your review plan.':'Progress through practice. This word is ready for review.');});
  if(!study&&!t.event&&t.stage!=='recognition')queueMicrotask(()=>$('#typed-answer')?.focus());
}
async function submitAnswer(answer){if(!task||task.event||!String(answer).trim())return;if(paused()){closeTask();return;}stopTimer();const t=task;const r=applyResult(profile(),{wordId:t.word.id,word:t.word.word,stage:t.stage,variant:t.variant,packVersion:pack.version},answer,t.assistance,elapsed(),Date.now(),state.settings.phase);t.event=r;drawTask();await save();}
function closeTask(){stopTimer();if(currentAudio){currentAudio.pause();currentAudio=null;}$('#task-dialog').close();task=null;render();}
$('#task-dialog').addEventListener('cancel',()=>{stopTimer();task=null;render();});
async function playAudio(w){try{currentAudio?.pause();currentAudio=new Audio(new URL(w.audio,import.meta.url).href);await currentAudio.play();}catch{toast('Pronunciation is unavailable. Save the offline pack while connected, then try again.');}}

function showProfiles(){let avatar='compass';$('#profile-dialog').innerHTML=`<div class="panel-title-row"><h2 id="profile-title">Choose your voyage emblem</h2><button class="close-button" data-close aria-label="Close learner profiles">×</button></div><p>Use a nickname or learner code. Each learner keeps their own progress on this device.</p><div class="profile-list">${state.profiles.map(p=>`<button class="profile-item ${p.id===state.activeId?'selected':''}" data-profile="${p.id}"><span class="avatar">${avatars[p.avatar]}</span>${esc(p.name)}<small>${p.id===state.activeId?'CURRENT':p.steps+' steps'}</small></button>`).join('')}</div><div class="dialog-section"><h3>Add a voyager</h3><form id="new-profile"><label class="field" for="profile-name">Nickname or learner code</label><input class="input" id="profile-name" maxlength="40" placeholder="For example, Navigator 07" required><label class="field">Choose a treasure emblem</label><div class="avatar-options">${Object.entries(avatars).map(([k,v])=>`<button type="button" class="avatar-choice ${k===avatar?'selected':''}" data-avatar="${k}" aria-label="${esc(avatarLabels[k]||k)} emblem" aria-pressed="${k===avatar}">${v}</button>`).join('')}</div><button class="primary" type="submit">Set sail →</button></form></div>`;const d=$('#profile-dialog');d.querySelector('[data-close]').onclick=()=>d.close();d.querySelectorAll('[data-profile]').forEach(b=>b.onclick=async()=>{state.activeId=b.dataset.profile;sessionSteps=0;d.close();render();await save();});d.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{avatar=b.dataset.avatar;d.querySelectorAll('[data-avatar]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});});$('#new-profile').onsubmit=async e=>{e.preventDefault();const name=$('#profile-name').value.trim();if(!name)return;if(state.profiles.length>=50){toast('This device has 50 profiles. Export a backup before using another device.');return;}const p=newProfile('lx-'+crypto.randomUUID(),name,avatar);state.profiles.push(p);state.activeId=p.id;sessionSteps=0;d.close();render();await save();toast('Your voyage is ready.');};d.showModal();}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportBackup(){download('lexitrek-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'lexitrek-backup',version:1,packId:pack.id,packVersion:pack.version,profiles:state.profiles,activeId:state.activeId,settings:state.settings},null,2),'application/json');toast('Backup exported. Keep it somewhere safe.');}
function exportCSV(){const keys=['learnerId','nickname','eventId','word','wordId','task','itemVariant','correct','assistance','independent','activeSeconds','dateUTC','phase','appVersion','packVersion'];const rows=state.profiles.flatMap(p=>p.events.filter(e=>e.type==='answer').map(e=>[p.id,p.name,e.id,pack.words.find(w=>w.id===e.wordId)?.word,e.wordId,e.stage,e.variant,e.correct,e.assistance.join(';'),e.independent,(e.activeMs/1000).toFixed(1),new Date(e.at).toISOString(),e.phase,e.appVersion,e.packVersion]));download('lexitrek-practice-log.csv',[keys.map(csvCell).join(','),...rows.map(r=>r.map(csvCell).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('Practice log exported. These are not outcome-test scores.');}
function showTeacher(){const d=$('#teacher-dialog');d.innerHTML=`<div class="panel-title-row"><h2 id="teacher-title">Teacher settings</h2><button class="close-button" data-close aria-label="Close teacher settings">×</button></div><p>Prepare learning, manage profiles, and document practice on this device.</p><div class="teacher-warning"><strong>Pilot word pack</strong><br>${pack.words.length} original cards across Pulse 2 Form 1 topic areas. Exact textbook page mapping, Malay support and scoring rules require teacher review before formal research. The app’s practice results do not replace independent pre-, post- or delayed vocabulary tests.</div><div class="dialog-section"><h3>Learning preferences</h3><label class="check-row"><input type="checkbox" id="setting-translation" ${state.settings.translation?'checked':''}>Start practice with Malay support</label><p class="teacher-note">These responses will be recorded as supported practice.</p><label class="check-row"><input type="checkbox" id="setting-motion" ${state.settings.reducedMotion?'checked':''}>Reduce movement and visual effects</label></div><div class="dialog-section"><h3>Study phase</h3><p>Applies to every profile on this device. Paused phases hide target-word teaching and review, online and offline.</p><label class="field" for="study-phase">Current phase</label><select class="input" id="study-phase">${PHASES.map(ph=>`<option value="${ph}" ${ph===state.settings.phase?'selected':''}>${phaseNames[ph]}</option>`).join('')}</select><p class="teacher-note">These are local pilot controls, not secure researcher authentication. Use separate standardised outcome assessments and record incidental exposure during the retention interval.</p></div><div class="dialog-section"><h3>Backups and research records</h3><p>Progress remains in this browser. Export a backup before clearing browser data or changing devices. No learner records are sent to a server.</p><div class="button-row"><button class="secondary" id="backup-export">Export backup</button><button class="secondary" id="backup-restore">Restore backup</button><button class="secondary" id="csv-export">Export practice CSV</button></div></div><div class="dialog-section"><h3>Content and version</h3><p>App ${VERSION} · Pack ${esc(pack.version)} · ${pack.words.length} provisional items.<br>Core target: A2 Mid Revised. Word-level CEFR classifications are not certified. Definitions and contexts are original; vocabulary selection follows Form 1 syllabus domains. Cambridge KET 2012 is a supplementary reference. Pronunciation files use a synthesised English voice.</p></div><div class="button-row" style="margin-top:22px"><button class="primary" id="save-settings">Save settings</button><button class="secondary" data-close-bottom>Cancel</button></div>`;d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('[data-close-bottom]').onclick=()=>d.close();$('#save-settings').onclick=async()=>{state.settings.translation=$('#setting-translation').checked;state.settings.reducedMotion=$('#setting-motion').checked;state.settings.phase=$('#study-phase').value;d.close();render();await save();toast('Learning settings saved on this device.');};$('#backup-export').onclick=exportBackup;$('#csv-export').onclick=exportCSV;$('#backup-restore').onclick=()=>$('#restore-file').click();d.showModal();}
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw new Error('This backup is too large.');const raw=JSON.parse(await file.text());if(raw.packId!==pack.id)throw new Error('This backup belongs to another vocabulary pack.');const valid=validateBackup(raw,pack.words.map(w=>w.id));if(!window.confirm(`Restore ${valid.profiles.length} learner profile(s)? This replaces the profiles on this device. Export your current backup first if you need to keep them.`))return;state={profiles:valid.profiles,activeId:valid.activeId,settings:valid.settings};sessionSteps=0;$('#teacher-dialog').close();render();await save();toast('Backup restored on this device.');}catch(error){toast(error.message||'This backup could not be restored.');}});
async function cacheStatus(){if(!registration?.active)return {ready:false};return swMessage({type:'STATUS'});}
function swMessage(data){return new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>reject(new Error('Offline preparation did not respond. Try again while connected.')),30000);channel.port1.onmessage=e=>{if(e.data.progress!==undefined){const meter=$('#offline-progress');if(meter)meter.style.width=e.data.progress+'%';const label=$('#offline-progress-label');if(label)label.textContent=`Saving ${e.data.done} of ${e.data.total} resources…`;return;}clearTimeout(timer);e.data.error?reject(new Error(e.data.error)):resolve(e.data);};registration.active.postMessage(data,[channel.port2]);});}
async function setupOffline(){if(!('serviceWorker'in navigator)){offlineError='This browser does not support offline installation.';return;}try{registration=await navigator.serviceWorker.register(new URL('./sw.js',import.meta.url),{scope:new URL('./',import.meta.url).pathname});await navigator.serviceWorker.ready;registration=await navigator.serviceWorker.getRegistration(new URL('./',import.meta.url).href);const r=await cacheStatus();offlineReady=r.ready;render();}catch(e){offlineError=e.message;}}
async function showOffline(){const d=$('#offline-dialog');d.innerHTML=`<div class="panel-title-row"><h2 id="offline-title">Your treasure hunt, anywhere.</h2><button class="close-button" data-close aria-label="Close offline details">×</button></div><p>Save all ${pack.words.length} word cards, their pronunciation, and the app. After a successful download, open LexiTrek on this device without internet.</p><div class="offline-meter"><i id="offline-progress" style="width:${offlineReady?100:0}%"></i></div><p id="offline-progress-label">${offlineReady?'The complete offline pack is ready.':offlineError||'Connect once to prepare your offline pack.'}</p><button class="primary" id="prepare-offline" ${!('serviceWorker'in navigator)?'disabled':''}>${offlineReady?'Check & refresh offline pack':'Save complete offline pack'} ${icon('download').replace('<svg','<svg width="16" height="16"')}</button><div id="offline-result"></div><div class="dialog-section"><h3>Add LexiTrek to your home screen</h3><p class="install-instructions">Android: use your browser’s install option.<br>iPhone or iPad: open in Safari, then Share → Add to Home Screen.<br>Desktop: use the install option in your browser.</p>${installPrompt?'<button class="secondary" id="install-app">Install LexiTrek</button>':''}<p class="teacher-note">Offline content and progress belong to this browser. Clearing browser data removes them. Export a progress backup before changing devices.</p></div>`;d.querySelector('[data-close]').onclick=()=>d.close();$('#prepare-offline').onclick=async()=>{const b=$('#prepare-offline');b.disabled=true;$('#offline-progress-label').textContent='Preparing the complete pack…';try{if(!registration?.active)await setupOffline();if(!registration?.active)throw new Error('Offline preparation is not available yet. Reload while connected and try again.');await swMessage({type:'PREPARE'});const checked=await cacheStatus();offlineReady=checked.ready;if(!offlineReady)throw new Error('Some resources are missing. Reconnect and try again.');await navigator.storage?.persist?.();$('#offline-progress').style.width='100%';$('#offline-progress-label').textContent='App, word cards and pronunciation saved.';$('#offline-result').innerHTML='<div class="readiness">✓ Ready for offline learning. Try reopening the app in airplane mode.</div>';toast('Your complete offline pack is ready.');render();}catch(e){$('#offline-progress-label').textContent=e.message;offlineReady=false;toast('Offline preparation is incomplete. Reconnect and retry.');}finally{b.disabled=false;}};$('#install-app')?.addEventListener('click',async()=>{await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;});d.showModal();}
$('#profile-switch').onclick=()=>state?showProfiles():toast('Learner profiles are not available yet.');$('#teacher-open').onclick=()=>state?showTeacher():toast('Recover saved data before changing settings.');

async function init(){try{const response=await fetch(new URL('./content.json',import.meta.url));if(!response.ok)throw new Error('The vocabulary pack could not be loaded.');pack=await response.json();let saved;try{saved=await openStore();}catch(e){toast(e.message+' Practice can continue, but export a backup before closing.');}if(saved){try{const valid=validateBackup({format:'lexitrek-backup',version:1,...saved},pack.words.map(w=>w.id));state={profiles:valid.profiles,activeId:valid.activeId,settings:valid.settings};}catch{recoveryData=saved;throw new Error('Saved progress needs recovery. Do not clear browser data. Export the recovery file and contact your teacher before continuing.');}}else{const p=newProfile('lx-'+crypto.randomUUID(),'Navigator');state={profiles:[p],activeId:p.id,settings:{phase:'learning',reducedMotion:false,translation:false}};await save();}render();setupOffline();}catch(e){$('#main').innerHTML=`<div class="error-box"><h2>We couldn’t prepare your treasure voyage.</h2><p>${esc(e.message)}</p><div class="button-row"><button class="secondary" id="reload-app">Try reloading</button>${recoveryData?'<button class="secondary" id="recovery-export">Export recovery file</button>':''}</div></div>`;$('#reload-app').onclick=()=>location.reload();$('#recovery-export')?.addEventListener('click',()=>download('lexitrek-recovery.json',JSON.stringify(recoveryData,null,2),'application/json'));}}
init();
